/* Experimental, untested PipeWire backend. Monitor routing is explicit. */
#include <pipewire/pipewire.h>
#include <spa/param/audio/format-utils.h>
#include <stdatomic.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <time.h>
#include <spa/buffer/meta.h>
#define BLOCK 480u
#define RING 256u
struct frame {uint32_t n,flags;uint64_t position,monotonic_ns;float samples[BLOCK];};
struct state {struct pw_main_loop *loop;struct pw_stream *stream;struct frame ring[RING];_Atomic unsigned write,read,failed,done,ready;int listing,first;const char *target;uint32_t target_id;struct spa_hook registry_hook,core_hook;};
static void quoted(const char *text){putchar('"');for(const unsigned char *p=(const unsigned char*)text;*p;p++){if(*p=='"'||*p=='\\'){putchar('\\');putchar(*p);}else if(*p>=32){putchar(*p);}}putchar('"');}
static void node(void *userdata,uint32_t id,uint32_t permissions,const char *type,uint32_t version,const struct spa_dict *props){(void)permissions;(void)version;struct state *s=userdata;if(strcmp(type,PW_TYPE_INTERFACE_Node)||!props)return;const char *kind=spa_dict_lookup(props,PW_KEY_MEDIA_CLASS);const char *name=spa_dict_lookup(props,PW_KEY_NODE_NAME);const char *description=spa_dict_lookup(props,PW_KEY_NODE_DESCRIPTION);if(!kind||!name)return;int mic=!strcmp(kind,"Audio/Source");int system=!strcmp(kind,"Audio/Sink");if(!mic&&!system)return;if(s->target&&!strcmp(name,s->target))s->target_id=id;if(!s->listing)return;if(!s->first)putchar(',');s->first=0;printf("{\"key\":\"pipewire:");for(const char*p=name;*p;p++){if(*p=='"'||*p=='\\')putchar('\\');putchar(*p);}printf(system?":monitor\",\"name\":":":mic\",\"name\":");quoted(description?description:name);printf(",\"kind\":\"%s\",\"is_default\":false,\"available\":true,\"experimental\":true}",mic?"mic":"system");}
static void removed(void *userdata,uint32_t id){struct state *s=userdata;if(s->target_id==id){atomic_store(&s->failed,1);pw_main_loop_quit(s->loop);}}
static const struct pw_registry_events registry_events={PW_VERSION_REGISTRY_EVENTS,.global=node,.global_remove=removed};
static void core_done(void *userdata,uint32_t id,int seq){(void)seq;if(id==PW_ID_CORE)pw_main_loop_quit(((struct state*)userdata)->loop);}
static const struct pw_core_events core_events={PW_VERSION_CORE_EVENTS,.done=core_done};
static void process(void *userdata){struct state *s=userdata;struct pw_buffer *buffer=pw_stream_dequeue_buffer(s->stream);if(!buffer)return;struct pw_time timing={0};if(pw_stream_get_time_n(s->stream,&timing,sizeof(timing))<0||timing.now<=0||!timing.rate.denom){atomic_store(&s->failed,1);pw_stream_queue_buffer(s->stream,buffer);return;}struct spa_data *data=&buffer->buffer->datas[0];struct spa_meta_header *meta=spa_buffer_find_meta_data(buffer->buffer,SPA_META_Header,sizeof(struct spa_meta_header));uint64_t timestamp=meta&&meta->pts>0?(uint64_t)meta->pts:(uint64_t)timing.now;uint64_t position=(uint64_t)((__uint128_t)timing.ticks*timing.rate.num*48000/timing.rate.denom);if(data->data&&data->chunk&&data->maxsize){uint32_t offset=data->chunk->offset%data->maxsize,size=SPA_MIN(data->chunk->size,data->maxsize-offset);const float *samples=(const float*)((const char*)data->data+offset);uint32_t frames=size/sizeof(float);for(uint32_t i=0;i<frames;i+=BLOCK){unsigned w=atomic_load_explicit(&s->write,memory_order_relaxed),r=atomic_load_explicit(&s->read,memory_order_acquire);if(w-r>=RING){atomic_store(&s->failed,1);break;}struct frame *f=&s->ring[w%RING];f->n=SPA_MIN(BLOCK,frames-i);f->position=position+i;f->monotonic_ns=timestamp+(uint64_t)i*1000000000u/48000;f->flags=0;memcpy(f->samples,samples+i,f->n*sizeof(float));atomic_store_explicit(&s->write,w+1,memory_order_release);}}pw_stream_queue_buffer(s->stream,buffer);}
static void stream_state(void *userdata,enum pw_stream_state old,enum pw_stream_state state,const char *error){(void)old;(void)error;struct state *s=userdata;if(state==PW_STREAM_STATE_ERROR||state==PW_STREAM_STATE_UNCONNECTED){atomic_store(&s->failed,1);pw_main_loop_quit(s->loop);}else if(state==PW_STREAM_STATE_PAUSED||state==PW_STREAM_STATE_STREAMING){atomic_store_explicit(&s->ready,1,memory_order_release);}}
static const struct pw_stream_events stream_events={PW_VERSION_STREAM_EVENTS,.state_changed=stream_state,.process=process};
static int emit(const struct frame *f){return fwrite(&f->n,4,1,stdout)==1&&fwrite(&f->position,8,1,stdout)==1&&fwrite(&f->monotonic_ns,8,1,stdout)==1&&fwrite(&f->flags,4,1,stdout)==1&&fwrite(f->samples,4,f->n,stdout)==f->n&&fflush(stdout)==0;}
static void *writer(void *userdata){struct state *s=userdata;int announced=0;while(!atomic_load(&s->done)){if(atomic_load(&s->failed)){pw_main_loop_quit(s->loop);break;}if(!announced&&atomic_load_explicit(&s->ready,memory_order_acquire)){struct timespec now;clock_gettime(CLOCK_MONOTONIC,&now);struct frame ready={.monotonic_ns=(uint64_t)now.tv_sec*1000000000u+now.tv_nsec};if(!emit(&ready)){atomic_store(&s->failed,1);break;}announced=1;}unsigned r=atomic_load_explicit(&s->read,memory_order_relaxed);if(r==atomic_load_explicit(&s->write,memory_order_acquire)){usleep(2000);continue;}struct frame *f=&s->ring[r%RING];if(!emit(f)){atomic_store(&s->failed,1);pw_main_loop_quit(s->loop);break;}atomic_store_explicit(&s->read,r+1,memory_order_release);}return NULL;}
int main(int argc,char **argv){if(argc<2)return 2;struct state *s=calloc(1,sizeof(*s));if(!s)return 1;s->listing=!strcmp(argv[1],"devices");s->first=1;s->target_id=PW_ID_ANY;pw_init(&argc,&argv);s->loop=pw_main_loop_new(NULL);struct pw_context *context=pw_context_new(pw_main_loop_get_loop(s->loop),NULL,0);struct pw_core *core=pw_context_connect(context,NULL,0);if(!core){fprintf(stderr,"PipeWire unavailable; start PipeWire and WirePlumber or explicitly choose PulseAudio monitor fallback.\n");return 1;}
 char target[1024]={0};int system=0;if(!s->listing){if(argc!=4||strncmp(argv[2],"pipewire:",9))return 2;snprintf(target,sizeof(target),"%s",argv[2]+9);char *suffix=strrchr(target,':');if(!suffix)return 2;system=!strcmp(suffix,":monitor");if(!system&&strcmp(suffix,":mic"))return 2;*suffix=0;s->target=target;}
 struct pw_registry *registry=pw_core_get_registry(core,PW_VERSION_REGISTRY,0);pw_registry_add_listener(registry,&s->registry_hook,&registry_events,s);pw_core_add_listener(core,&s->core_hook,&core_events,s);if(s->listing)putchar('[');pw_core_sync(core,PW_ID_CORE,0);pw_main_loop_run(s->loop);if(s->listing){puts("]");return 0;}if(s->target_id==PW_ID_ANY){fprintf(stderr,"Selected PipeWire node disappeared; reselect explicitly.\n");return 1;}
 struct pw_properties *props=pw_properties_new(PW_KEY_MEDIA_TYPE,"Audio",PW_KEY_MEDIA_CATEGORY,"Capture",PW_KEY_MEDIA_ROLE,"Communication",PW_KEY_TARGET_OBJECT,target,"stream.capture.sink",system?"true":"false",NULL);s->stream=pw_stream_new_simple(pw_main_loop_get_loop(s->loop),"Meeting Assistant explicit capture",props,&stream_events,s);uint8_t buffer[1024];struct spa_pod_builder builder=SPA_POD_BUILDER_INIT(buffer,sizeof(buffer));struct spa_audio_info_raw format={.format=SPA_AUDIO_FORMAT_F32,.rate=48000,.channels=1,.position={SPA_AUDIO_CHANNEL_MONO}};const struct spa_pod *params[]={spa_format_audio_raw_build(&builder,SPA_PARAM_EnumFormat,&format)};
 if(pw_stream_connect(s->stream,PW_DIRECTION_INPUT,PW_ID_ANY,PW_STREAM_FLAG_AUTOCONNECT|PW_STREAM_FLAG_MAP_BUFFERS|PW_STREAM_FLAG_RT_PROCESS,params,1)<0)return 1;pthread_t thread;pthread_create(&thread,NULL,writer,s);pw_main_loop_run(s->loop);atomic_store(&s->done,1);pthread_join(thread,NULL);pw_stream_destroy(s->stream);pw_core_disconnect(core);pw_context_destroy(context);pw_main_loop_destroy(s->loop);return atomic_load(&s->failed)?1:0;
}
